// Renders brief cards from window.BRIEFS (generated by tools/build-index.ps1).
(function () {
  const SLOT = {
    morning:   { zh: '早报', en: 'Morning Brief', cls: 'tag-morning' },
    afternoon: { zh: '午后速递', en: 'Afternoon Check', cls: 'tag-afternoon' },
    weekend:   { zh: '周末版', en: 'Weekend Brief', cls: 'tag-weekend' }
  };
  const WD_ZH = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];

  function esc(s) {
    return String(s || '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }
  function dateParts(iso) {
    const [y, m, d] = iso.split('-').map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d));
    return {
      zh: `${y}年${m}月${d}日 · ${WD_ZH[dt.getUTCDay()]}`,
      en: dt.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' })
    };
  }

  window.kpBriefs = {
    SLOT, dateParts,
    all() {
      return (window.BRIEFS || []).slice().sort((a, b) =>
        b.date.localeCompare(a.date) || (b.order || 0) - (a.order || 0));
    },
    url(b, root) { return (root || '') + 'briefs/' + b.file; },
    card(b, root) {
      const s = SLOT[b.slot] || SLOT.morning;
      const d = dateParts(b.date);
      const hz = b.headlineZh || b.headlineEn || '';
      const he = b.headlineEn || b.headlineZh || '';
      return `
<a class="brief-card" href="${this.url(b, root)}">
  <div class="brief-top">
    <span class="tag ${s.cls}"><span class="zh">${s.zh}</span><span class="en">${s.en}</span></span>
    <span class="brief-date"><span class="zh">${d.zh}</span><span class="en">${d.en}</span></span>
  </div>
  <p class="brief-headline"><span class="zh">${esc(hz)}</span><span class="en">${esc(he)}</span></p>
  <span class="brief-more"><span class="zh">阅读简报 →</span><span class="en">Read brief →</span></span>
</a>`;
    }
  };
})();
